; [LevelLoad] Processes level-specific logic and events.
ProcessLevelLogic:
        PHB
        PHP
        PHK
        PLB
        REP #$30
        PHD
        LDA.W #$0600
        TCD
        JSR.W GameLogicDispatcher
        LDA.W #$0700
        TCD
        JSR.W GameLogicDispatcher
        LDA.W $059E
        BNE ReturnCleanup
        LDA.W #$0800
        TCD
        JSR.W GameLogicDispatcher
        LDA.W #$0900
        TCD
        JSR.W GameLogicDispatcher
        LDA.W #$0A00
        TCD
        JSR.W GameLogicDispatcher
; [Helper] Clean return with PLD/PLP/PLB/RTL
ReturnCleanup:
        PLD
        PLP
        PLB
        RTL
; [GameState] Main game logic dispatcher. Checks $2E flag, calls appropriate game logic routines. Entry: 8-bit A, 16-bit X/Y, preserves flags
GameLogicDispatcher:
        PHP
        SEP #$20
        LDA.B $00
        BNE DispatchGameLogic
        JMP.W CheckGameModeCondition
; [GameState] Main game logic dispatcher. Checks $2E flag, calls appropriate game logic routines.
DispatchGameLogic:
        LDA.B $2E
        BEQ ProcessGameLogic
        JSL.L ClearObjectStateAndDispatch
; [GameState] Processes game logic, checks $125F flag
ProcessGameLogic:
        JSL.L HandleGameLogic
        LDA.W $125F
        BEQ CheckGameMode
        db $4C,$07,$9C
; [GameState] Checks game mode $00C8 for values $04 or $16
CheckGameMode:
        LDA.W $00C8
        CMP.B #$04
        BEQ HandleSpecialGameModes
        CMP.B #$16
        BEQ HandleSpecialGameModes
        JMP.W CallExternalRoutineE8D2
; [GameState] Handles special game modes $04 and $16
HandleSpecialGameModes:
        REP #$20
        LDA.B $D2
        BEQ CheckObjectFlags
        DEC.B $D2
; [Entity] Checks object flags in $056C/$056D arrays
CheckObjectFlags:
        SEP #$20
        LDA.B #$00
        XBA
        LDA.B $28
        TAX
        LDA.W $056C,X
        BIT.B #$30
        BEQ CheckObjectState2
        JSL.L processSoundEffect
        BRA DecrementGameTimers
; [Entity] Checks object state $056D for value $C0
CheckObjectState2:
        LDA.B #$00
        XBA
        LDA.B $28
        TAX
        LDA.W $056D,X
        CMP.B #$C0
        BNE CheckObjectFlag80
        JMP.W DispatchObjectSubtype
; [Entity] Checks $056C flag bit $80
CheckObjectFlag80:
        LDA.W $056C,X
        BIT.B #$80
        BEQ CheckObjectFlag80b
        JMP.W UpdateObjectTimers
; [Entity] Checks $056D flag bit $80
CheckObjectFlag80b:
        LDA.W $056D,X
        BIT.B #$80
        BEQ ProcessObjectFlagsAndTimers
        JMP.W FireObjectProjectile
; [Entity] Processes object flags at $056C,X and $0560,X, decrements game timers $46, $AC, $55, $5D. Entry: 8-bit A.
ProcessObjectFlagsAndTimers:
        LDA.W $056C,X
        BIT.B #$40
        BEQ ProcessObjectFlag40
        JMP.W FinalizeObjectRendering
; [Entity] Processes object flag $40 in $0560,X
ProcessObjectFlag40:
        LDA.W $0560,X
        BIT.B #$40
        BEQ DecrementGameTimers
        JSR.W LoadObjectBehaviorTable
        BRA DecrementGameTimers
; [Timer] Decrements multiple game timers: $46, $AC, $55, $5D. Calls external routines.
DecrementGameTimers:
        REP #$30
        JSR.W DispatchObjectHandler
        SEP #$20
        LDA.W $12E2
        BEQ DecrementTimer46
; [Timer] Decrements timer $46 if non-zero
DecrementTimer46:
        LDA.B $46
        BEQ DecrementTimerAC
        DEC.B $46
; [Timer] Decrements timer $AC if non-zero
DecrementTimerAC:
        LDA.B $AC
        BEQ DecrementTimer55
        DEC.B $AC
; [Timer] Decrements timer $55 if non-zero
DecrementTimer55:
        LDA.B $55
        BEQ DecrementTimer5D
        DEC.B $55
; [Timer] Decrements timer $5D if non-zero.
DecrementTimer5D:
        LDA.B $5D
        BEQ CallExternalRoutineE8D2
        DEC.B $5D
; [Helper] Calls external routine at $82E8D2, checks $1E08 flag.
CallExternalRoutineE8D2:
        JSL.L SetupDispatchPointer
        LDA.W $1E08
        BNE DispatchGameModeRoutine
        JSL.L CheckEntityConditions
; [GameState] Dispatches to game mode routine based on $0A value via jump table at $8119
DispatchGameModeRoutine:
        LDA.B #$00
        XBA
        LDA.B $0A
        TAX
        JMP.W ($8119,X)
; [GameState] Checks game mode condition: examines $1E08, direct page high byte for values 6-7.
CheckGameModeCondition:
        LDA.W $1E08
        BEQ ValidateGameMode
        JMP.W CheckGameMode04or16_2
; [GameState] Validates game mode $00C8 for values $04 or $16.
ValidateGameMode:
        TDC
        XBA
        CMP.B #$06
        BEQ CheckGameMode04or16
        CMP.B #$07
        BEQ CheckGameMode04or16
        PLP
        RTS
; [GameState] Checks if game mode is $04 or $16, calls game condition check.
CheckGameMode04or16:
        SEP #$20
        LDA.W $00C8
        CMP.B #$04
        BEQ CheckGameConditionWrapper
        CMP.B #$16
        BEQ CheckGameConditionWrapper
        PLP
        RTS
; [GameState] Wrapper that calls CheckGameCondition JSL then returns
CheckGameConditionWrapper:
        JSL.L CheckGameCondition
        PLP
        RTS
        db $21,$82,$E1,$9E,$60,$A6,$71,$A7,$A6,$C6,$22,$C6,$F4,$CB,$64,$D0
        db $68,$D0,$3C,$D2,$40,$D2,$44,$D2,$48,$D2,$4C,$D2,$50,$D2,$54,$D2
