        db $A7,$81,$A7,$81,$A7,$81,$A9,$81,$A9,$81,$A7,$81,$A9,$81,$A9,$81
        db $A7,$81
        db $A7,$81,$A7,$81,$A7,$81,$A7,$81,$A7,$81,$A7,$81
; [Helper] Returns from object handler (PLP/RTS)
ReturnFromObjectHandler:
