; [Helper] Simple return from object processing
ReturnFromObjectProc:
        PLP
        RTS
; [StateMachine] Object state machine dispatcher with jump table at $8281D6
ObjectStateMachine:
        PHP
        SEP #$30
        LDX.B $0A
        JMP.W ($81D6,X)
        db $16,$82
        db $1F,$82,$16,$82,$1F,$82,$1F,$82,$1F,$82,$1F,$82,$1F,$82,$1F,$82
        db $16,$82,$1F,$82,$1F,$82,$16,$82,$16,$82,$1F,$82,$16,$82,$1F,$82
