; [StateMachine] Dispatches to object handler based on $27 value using jump table at $823C. Entry: 8-bit A/X/Y
DispatchObjectByType:
        SEP #$30
        LDX.B $27
        JMP.W ($823C,X)
        db $0D,$83,$7C,$82,$0D,$83,$0D,$83,$0D,$83,$0D,$83,$0D,$83,$0D,$83
        db $0D,$83,$0D,$83,$0D,$83,$0D,$83,$0D,$83,$0D,$83
        db $0D,$83,$0D,$83,$0D,$83
        db $0D,$83,$0D,$83,$0D,$83,$0D,$83,$0D,$83,$0D,$83,$0D,$83,$0D,$83
        db $0D,$83
