; [Entity] Processes object sequence: checks $10 value, manages sequence counter $0E.
ProcessObjectSequence:
        LDA.B $10
        CMP.B #$01
        BNE UpdateObjectCounter
        JSR.W ClearVariables11_15
; [Entity] Updates object counter $0E, compares with $1E, resets or increments $10.
UpdateObjectCounter:
        LDA.B #$03
        STA.B $1D
        REP #$10
        INC.B $0E
        LDA.B $0E
        CMP.B $1E
        BNE CallObjectRoutines
