; [Entity] Loads object parameter from table $82FD based on $10 index.
LoadObjectParameter:
        LDA.B #$00
        XBA
        LDA.B $10
        DEC A
        TAX
        LDA.W $82FD,X
        STA.B $1E
        JMP.W CallObjectRoutines
; [Entity] Initializes object handler: if $1D=0, clears $0E/$54 and calls $93F4, otherwise decrements $1D.
InitObjectHandler:
        LDA.B $1D
        BNE UpdateObjectHandler
        STZ.B $0E
        STZ.B $54
        JSR.W ClearVariables11_15
        BRA CallObjectRoutines
; [Entity] Updates object handler: decrements $1D timer and calls $93F4.
UpdateObjectHandler:
        DEC.B $1D
        JSR.W ClearVariables11_15
; [Entity] Calls object routine at $9290, jumps to $8471.
CallObjectRoutines:
        JSR.W ProcessBehaviorJump
