        db $30,$0C
        db $60,$0C,$90,$0C,$C0,$0C
        db $F0,$0C
; [Entity] Default object handler for most object types. Dispatches further based on $2E value.
DefaultObjectHandler:
        LDX.B $2E
        JMP.W ($8312,X)
        db $72,$83,$16,$83
        LDX.B $28
        LDA.W $0561,X
        AND.B #$0F
        STA.B $26
        BNE CompareObjectCoordinates
        JMP.W ProcessGraphicsData
; [Collision] Compares object coordinates with reference values, sets $2A flag based on comparison results
CompareObjectCoordinates:
        ASL A
        ASL A
