; [Collision] Checks object Y position against reference, sets $2A flag based on comparison.
CheckObjectPosition:
        STA.B $2A
        REP #$20
        LDA.W $0005,X
        CLC
        ADC.W #$0010
        CMP.B $05
        BCC SetObjectFlag08
        SEP #$30
