; [Entity] Sets object flag to $08 when Y position check fails.
SetObjectFlag08:
        SEP #$30
        LDA.B #$08
; [Entity] Jumps to object processing routine at $83A5.
JumpToObjectProcessing:
        JMP.W CalculateObjectOffset
; Processes graphics data for rendering
ProcessGraphicsData:
        LDA.B $1D
        BNE DecrementTimer1D
        LDA.B $54
        STA.B $10
        STZ.B $0E
        JSR.W ClearVariables11_15
        BRA JumpTo846E
; [Timer] Decrements timer $1D and jumps to $846B
DecrementTimer1D:
        DEC.B $1D
        JMP.W JumpTo846B_3
; [Helper] Jumps to routine at $846E
JumpTo846E:
        JMP.W JumpTo846E_2
        LDA.B $D5
        BEQ CheckTimersAndSetValue
        DEC.B $D5
        JMP.W CheckTimer1DAndReset
; [Timer] Checks timers $26 and $1D, sets $10 from $A4 if both zero
CheckTimersAndSetValue:
        LDA.B $26
        BNE ReadPlayerInputMask
        LDA.B $1D
        BNE ReadPlayerInputMask
        LDA.B $A4
