; [Entity] Advances to next entity: X+=256, checks if X=$0B00 (end), loops back to ProcessEntityList.
AdvanceToNextEntity:
        REP #$20
        TXA
        CLC
        ADC.W #$0100
        CMP.W #$0B00
        BEQ EndEntityProcessing
        TAX
        JMP.W ProcessEntityList
; [Entity] Ends entity processing: restores flags and returns.
EndEntityProcessing:
        PLP
        PLB
        RTL
; [Entity] Checks if entity type $0A,X is $3C, branches based on comparison.
CheckEntityType3C:
        SEP #$20
        LDA.W $000A,X
        CMP.B #$3C
        BEQ UpdateScriptState
        CMP.B #$26
        BEQ UpdateScriptState
        LDA.W $12CE
        BNE SetEntityStateC
        LDA.B #$0E
        BRA StoreEntityState
; [Entity] Sets entity state $0C,X based on comparison: 4->2, 8->0C, otherwise returns.
SetEntityStateC:
        CMP.B #$04
        BNE CheckEntityType8
        LDA.B #$02
        BRA StoreEntityState
; [Entity] Checks if entity type is 8, sets $0C,X=0C if true.
CheckEntityType8:
        CMP.B #$08
        BNE UpdateScriptState
        LDA.B #$0C
; [Entity] Stores entity state A to $0C,X.
StoreEntityState:
        STA.W $000C,X
; [Script] Updates script state variables. Entry: 8-bit A, 16-bit X/Y
UpdateScriptState:
        RTS
        LDA.B #$04
        STA.W $12ED
        STZ.W $12EE
        INC.W $12EC
        PLP
        PLB
        RTL
        LDA.W $12ED
        BNE UnknownFunctionF66
        INC.W $12EC
; [Unknown] Function at $DF66 - needs analysis. Entry: 8-bit A, 16-bit X/Y.
UnknownFunctionF66:
        PLP
        PLB
        RTL
        INC.W $12EC
        REP #$20
        LDA.W #$007F
        LDX.W #$0080
        LDY.W #$F000
        MVN $7F,$00
        LDA.W #$00FF
        LDX.W #$0320
        LDY.W #$F080
        MVN $7F,$00
        LDA.W #$0011
        LDX.W #$0520
        LDY.W #$F180
        MVN $7F,$00
        SEP #$20
        LDA.B #$00
        PHA
        PLB
        STZ.W $00A6
        STZ.W $00A7
        STZ.W $00A8
        PLP
        PLB
        RTL
        LDA.W $12ED
        BNE LoadGraphicsData
        INC.W $12EC
; Loads graphics data based on $12CE and $12D0. Uses table at $E18D for pointer lookup, stores to $0E22 buffer.
LoadGraphicsData:
        PLP
        PLB
        RTL
        REP #$30
        LDX.W $12CE
        LDA.W $E18D,X
        STA.B $00
        LDY.W #$0000
        LDA.W $12D0
        ASL A
        ASL A
        ASL A
        TAY
        LDX.W $0F22
        LDA.B ($00),Y
        CMP.W #$FFFF
        BEQ UnknownFunctionFF3
        STA.W $0E22,X
        INY
        INY
        LDA.B ($00),Y
        STA.W $0E24,X
        INY
        INY
        LDA.B ($00),Y
        STA.W $0E26,X
        INY
        INY
        LDA.B ($00),Y
        STA.W $0E28,X
        INC.W $12D0
        TXA
        CLC
        ADC.W #$0008
        STA.W $0F22
        PLP
        PLB
        RTL
; [Unknown] Function at $DFF3 - needs analysis. Entry: 16-bit A/X/Y.
UnknownFunctionFF3:
        REP #$20
        LDA.W $12CE
        AND.W #$000F
        TAX
        LDA.W $E01A,X
        BEQ IncrementCounterAndReturn
        STA.W $1288
        LDA.W $0521
        CLC
        ADC.W #$0080
        STA.W $128A
        JSL.L CalculateAudioVolume
; [Helper] Increments $12EC counter and returns from subroutine.
IncrementCounterAndReturn:
        SEP #$20
        INC.W $12EC
        PLP
        PLB
        RTL
        db $2A,$00,$2B,$00,$00,$00,$00,$00,$00,$00
        SEP #$20
        REP #$10
