        STX.W $4345
        LDX.W #$0000
        STX.W $4347
        LDA.B #$80
        STA.W $00C0
        LDX.W #$0000
; [Memory] Initializes memory areas $7EE500-$7EF192 with pattern: $01 at $E500,X, zeros at $EEC0-$EEC2,X and $F190-$F192,X.
InitializeMemoryAreas:
        LDA.B #$01
        STA.L $7EE500,X
        INX
        INX
        INX
        LDA.B #$00
        STA.L $7EEEC0,X
        STA.L $7EEEC1,X
        STA.L $7EEEC2,X
        STA.L $7EF190,X
        STA.L $7EF191,X
        STA.L $7EF192,X
