        STZ.W $12DC
        STZ.W $12D2
        LDA.W #$0014
        STA.W $12D6
        LDA.W #$0200
        STA.W $12D4
        STZ.W $12D8
        STZ.W $1660
        STZ.W $1662
        LDA.W #$0003
        STA.W $1664
        LDA.W #$0003
        STA.W $1666
        STZ.W $1668
        JMP.W CopyDataBlockFromTable
; [Entity] Sets entity parameters based on $12CE and $0625. If $12CE≠0 or $0625≠$20, sets default: $A5=$31, $A0=$15, $A1=$02. Otherwise sets: $A5=$22, $A0=$17, $A1=$11.
SetEntityParameters:
        PHP
        SEP #$20
        LDA.W $12CE
        BNE SetDefaultEntityParams
        LDA.W $0625
        CMP.B #$20
        BNE SetDefaultEntityParams
        LDA.B #$22
        STA.W $00A5
        LDA.B #$17
        STA.W $00A0
        LDA.B #$11
        STA.W $00A1
        BRA ReturnFromParamSet
; [Entity] Sets default entity parameters: $A5=$31, $A0=$15, $A1=$02.
SetDefaultEntityParams:
        LDA.B #$31
        STA.W $00A5
        LDA.B #$15
        STA.W $00A0
        LDA.B #$02
        STA.W $00A1
; [Helper] Returns from parameter setting subroutine.
ReturnFromParamSet:
        PLP
        RTS
        JSR.W SetEntityParameters
        INC.W $12EC
        LDA.B #$29
        STA.W $0082
        REP #$20
        STZ.W $12DC
        STZ.W $12D2
        STZ.W $12D4
        STZ.W $12D6
        STZ.W $12D8
; [Memory] Copies 31-byte block from table at $E183 indexed by $12CE to $00:0400. Entry: 16-bit A/X/Y.
CopyDataBlockFromTable:
        REP #$30
        LDX.W $12CE
        LDA.W $E183,X
        TAX
        PHB
        LDY.W #$0400
        LDA.W #$001F
        MVN $00,$C0
        PLB
        STZ.W $0527
        STZ.W $052A
        PLP
        PLB
        RTL
        JSR.W SetEntityParameters
        INC.W $12EC
        LDA.B #$29
        STA.W $0082
        LDA.B #$52
        STA.W $0085
        REP #$20
        STZ.W $12DC
        STZ.W $12D2
        STZ.W $12D4
        STZ.W $12D6
        STZ.W $12D8
        STZ.W $12DA
        STZ.W $1660
        STZ.W $1660
        STZ.W $1662
        STZ.W $1664
        LDA.W #$00B4
        STA.W $1666
        STA.W $166A
        JMP.W CopyDataBlockFromTable
        db $40,$08,$60,$08,$80,$08,$D0,$0F,$D0,$18,$2D,$E2,$C9,$E1,$FB,$E1
        db $97,$E1,$FB,$E1,$80,$58,$07,$CF,$00,$08,$00,$30,$80,$58,$0F,$CF
        db $00,$08,$00,$34,$80,$58,$17,$CF,$00,$08,$00,$38,$80,$58,$1F,$CF
        db $00,$08,$00,$3C,$80,$58,$27,$CF,$00,$08,$00,$50,$80,$58,$2F,$CF
        db $00,$08,$00,$54,$FF,$FF,$80,$1A,$2A,$C9,$00,$08,$00,$30,$80,$1A
        db $32,$C9,$00,$08,$00,$34,$80,$1A,$3A,$C9,$00,$08,$00,$38,$80,$1A
        db $42,$C9,$00,$08,$00,$3C,$80,$1A,$4A,$C9,$00,$08,$00,$50,$80,$1A
        db $52,$C9,$00,$08,$00,$54,$FF,$FF,$80,$1A,$5A,$C9,$00,$08,$00,$30
        db $80,$1A,$62,$C9,$00,$08,$00,$34,$80,$1A,$6A,$C9,$00,$08,$00,$38
        db $80,$1A,$72,$C9,$00,$08,$00,$3C,$80,$1A,$7A,$C9,$00,$08,$00,$50
        db $80,$1A,$82,$C9,$00,$08,$00,$54,$FF,$FF,$80,$1A,$12,$C9,$00,$06
        db $00,$30,$80,$1A,$18,$C9,$00,$06,$00,$33,$80,$1A,$1A,$C9,$00,$04
        db $00,$50,$80,$1A,$1E,$C9,$00,$04,$00,$52,$80,$1A,$22,$C9,$00,$04
        db $00,$54,$80,$1A,$26,$C9,$00,$04,$00,$56,$FF,$FF
        REP #$30
        LDA.W $12DC
        ASL A
        TAX
        JMP.W ($E269,X)
        db $6F,$E2,$AA,$E2,$4C,$E3
        JSR.W UpdateAnimationFrame
        JSR.W UpdateScrollPosition
        LDA.W $12DE
        LSR A
        BCC IncrementCounterD6
        LDA.W #$0013
        STA.W $12D8
        BRA CheckCounterLimit
; [Helper] Increments $12D6 by 2, updates animation/counter value.
IncrementCounterD6:
        LDA.W $12D6
        CLC
        ADC.W #$0002
        STA.W $12D6
; [GameState] Checks if $12D2 < $02E0, caps at $02E0, resets $12D6, increments $12DC, sets $12DA=$78 if limit reached.
CheckCounterLimit:
        LDA.W $12D2
        CMP.W #$02E0
        BCC ProcessScriptLogic
        LDA.W #$02E0
        STA.W $12D2
        STZ.W $12D6
        INC.W $12DC
        LDA.W #$0078
        STA.W $12DA
; [Script] Processes script logic. Entry: 16-bit A/X/Y
ProcessScriptLogic:
        PLP
        PLB
        RTL
        REP #$20
        JSR.W UpdateAnimationFrame
        JSR.W UpdateScrollPosition
        LDA.W $12D8
        INC A
        STA.W $12D8
        STZ.W $12D6
        DEC.W $12DA
        BEQ IncrementCounterDC
        PLP
        PLB
        RTL
; [Helper] Increments $12DC counter and returns.
IncrementCounterDC:
        REP #$20
        INC.W $12DC
        PLP
        PLB
        RTL
; [Animation] Updates animation frame based on $12DE. Increments $12E0 every 4 frames, uses table at $E54D for frame data.
UpdateAnimationFrame:
        PHP
        REP #$30
        LDA.W $12DE
        AND.W #$0003
        BNE ContinueAnimationUpdate
        INC.W $12E0
; [Animation] Continues animation update: loads frame data from table $E54D based on $12E0.
ContinueAnimationUpdate:
        LDA.W $12E0
        AND.W #$0003
        ASL A
        TAX
        LDA.W $E54D,X
        TAY
        LDA.W $E55D
        STA.B $00
        LDA.W #$00C0
        STA.B $02
        LDA.B [$00],Y
        STA.W $041E
        PLP
        RTS
; [Scrolling] Updates scroll position based on $12DE parity. If odd: clears $052A, X=0; if even: sets $052A=$0100, X=2.
UpdateScrollPosition:
        PHP
        REP #$30
        LDA.W $12DE
        LSR A
        BCC SetEvenFrameScroll
        STZ.W $052A
        LDX.W #$0000
        BRA UpdatePositionValue
; [Scrolling] Sets even frame scroll: $052A=$0100, X=2 for indexing.
SetEvenFrameScroll:
        LDA.W #$0100
        STA.W $052A
        LDX.W #$0002
; [Physics] Updates position value: $12D2,X += $12D6,X, stores result to $0527.
UpdatePositionValue:
        LDA.W $12D2,X
        CLC
        ADC.W $12D6,X
        STA.W $12D2,X
        STA.W $0527
        PLP
        RTS
; [Physics] Updates alternate position (similar to $E2F7 but for different axis).
UpdateAlternatePosition:
        PHP
        REP #$30
        LDA.W $12DE
        LSR A
        BCC UpdateVerticalPosition
        LDX.W #$0000
        LDA.W #$0000
        STA.W $0527
        BRA UpdatePositionLoop
; [Physics] Updates vertical position: X=2, sets $0527=$0200, adds $12D6,X to $12D2,X, stores to $052A.
UpdateVerticalPosition:
        LDX.W #$0002
        LDA.W #$0200
        STA.W $0527
; [Physics] Loop body for position update: adds $12D6,X to $12D2,X, stores to $052A.
UpdatePositionLoop:
        LDA.W $12D2,X
        CLC
        ADC.W $12D6,X
        STA.W $12D2,X
        STA.W $052A
        PLP
        RTS
        SEP #$20
        INC.W $12EC
        LDA.B #$15
        STA.W $00A0
        STZ.W $00A1
        STZ.W $1655
        PLP
        PLB
        RTL
        SEP #$20
        LDA.B #$01
        STA.W $1655
        REP #$30
        INC.W $1666
        LDA.W $1666
        AND.W #$003F
        BNE UpdateScriptVariables
        LDA.W #$002F
        JSL.L SetupDataProcessing80
; [Script] Updates script variables. Entry: 16-bit A/X/Y
UpdateScriptVariables:
        REP #$20
        LDA.W $12DC
        ASL A
        TAX
        JMP.W ($E384,X)
        db $88,$E3,$4C,$E3
        STZ.W $0527
        JSR.W UpdateAnimationFrame
        JSR.W UpdateAlternatePosition
        LDA.W $12D6
        AND.W #$01FF
        STA.W $12D6
        JSR.W ProcessState0
        LDA.W $12D2
        CMP.W #$0800
        BCC ClearFlagAndReturn
        INC.W $12DC
; [Helper] Clears $1655 flag and returns from long subroutine. Entry: 8-bit A, restores flags/bank.
ClearFlagAndReturn:
        SEP #$20
        STZ.W $1655
        PLP
        PLB
        RTL
; [StateMachine] State 0 handler for state machine. Entry: saves flags, 16-bit mode.
ProcessState0:
        PHP
        REP #$30
        LDA.W $12DE
        LSR A
        BCS JumpToIncrementCounter
        JMP.W IncrementCounter1660
; [Helper] Jumps to $E3BF to increment counter and process.
JumpToIncrementCounter:
        JMP.W IncrementCounter1662
; [Helper] Increments $1662 counter, stores in $00, sets X=0 for processing.
IncrementCounter1662:
        INC.W $1662
        LDA.W $1662
        AND.W #$00FF
        STA.B $00
        LDX.W #$0000
; Looks up graphics value using $00, processes result in $02.
LookupGraphicsAndProcess:
        LDA.B $00
        JSL.L LookupGraphicsValue
        STA.B $02
        LDA.B $02
        LSR A
        LSR A
        LSR A
        LSR A
        LSR A
        CLC
        ADC.W #$0200
        STA.L $7EE501,X
        INX
        INX
        INX
        LDA.B $00
        INC A
        AND.W #$00FF
        STA.B $00
        CPX.W #$02D0
        BNE LookupGraphicsAndProcess
        PLP
        RTS
; [Helper] Increments $1660 counter, adds 4 to $1668, stores counter in $00.
IncrementCounter1660:
        INC.W $1660
        LDA.W $1668
        CLC
        ADC.W #$0004
        STA.W $1668
        LDA.W $1660
        AND.W #$00FF
        STA.B $00
        LDX.W #$0000
; Draws pixel using $00, stores result in buffer at $7EE501+X.
DrawPixelAndStore:
        LDA.B $00
        JSL.L DrawPixelToBuffer
        REP #$20
        LSR A
        CLC
        ADC.W $1668
        STA.L $7EE501,X
        INX
        INX
        INX
        LDA.B $00
        INC A
        AND.W #$00FF
        STA.B $00
