        BNE DrawPixelAndStore
        PLP
        RTS
        REP #$30
        LDA.W $12DC
        ASL A
        TAX
        JMP.W ($E43B,X)
        db $3F,$E4,$4C,$E3
        LDA.W $1666
        AND.W #$001F
        BNE DecrementCounter1666
        LDA.W #$0033
        JSL.L SetupDataProcessing80
; [Helper] Decrements $1666, advances state if zero, otherwise continues.
DecrementCounter1666:
        DEC.W $1666
        BNE IncrementCounter12DA
        INC.W $12DC
        PLP
        PLB
        RTL
; [Helper] Increments $12DA, resets at 10, manages $1660 animation counter.
IncrementCounter12DA:
        INC.W $12DA
        LDA.W $12DA
        CMP.W #$000A
        BNE SetAnimationValues
        STZ.W $12DA
        INC.W $1660
        LDA.W $1660
        CMP.W #$0003
        BNE SetAnimationValues
        STZ.W $1660
; [Animation] Sets $12D6/$12D8 animation values, calls $E48A, returns.
SetAnimationValues:
        JSR.W UpdateAnimationFrame
        LDA.W #$FFFD
        STA.W $12D6
        LDA.W #$FFF8
        STA.W $12D8
        JSR.W CheckAnimationBit
        PLP
        PLB
        RTL
; [Animation] Checks $12DE bit 0, branches based on animation state.
CheckAnimationBit:
        PHP
        REP #$30
        LDA.W $12DE
        LSR A
        BCC LoadAnimationFrame
        LDA.W $1660
        ASL A
        TAX
        LDA.W $E4D3,X
        STA.W $052A
        LDA.W #$0000
        LDX.W #$0000
        BRA StoreAnimationData
; [Animation] Loads animation frame data based on $1660 counter.
LoadAnimationFrame:
        LDA.W $1660
        ASL A
        TAX
        LDA.W $E4D9,X
        CLC
        ADC.W $166A
        STA.W $052A
        INC.W $166A
        LDA.W $166A
        AND.W #$01FF
        STA.W $166A
        LDX.W #$0002
; [Animation] Stores animation data to $12D2-$12D5 registers.
StoreAnimationData:
        LDA.W $12D2,X
        CLC
        ADC.W $12D6,X
        STA.W $12D2,X
        STA.W $0527
        PLP
        RTS
        db $EE,$FF,$EE,$01,$EE,$00,$12,$01,$12,$00,$12,$02
        REP #$30
        DEC.W $12D4
        BEQ UpdateAnimationRegisters
        INC.W $12D2
        LDA.W $12D2
        AND.W #$0003
        BNE CalculateAnimationOffset
        INC.W $12D8
; [Animation] Calculates animation offset for frame rendering.
CalculateAnimationOffset:
        JSR.W ReturnFromAnimation
        LDA.W $12D8
        AND.W #$0007
        ASL A
        ASL A
        TAX
        LDA.W $E56D,X
        STA.W $0527
        LDA.W $E56F,X
        STA.W $052A
        PLP
        PLB
        RTL
; [Animation] Updates $12D2-$12D5 animation registers with new values.
UpdateAnimationRegisters:
        SEP #$20
        INC.W $12EC
        LDA.B #$15
        STA.W $00A0
        STZ.W $00A1
        PLP
        PLB
        RTL
; [Helper] Simple return from animation subroutine.
ReturnFromAnimation:
        PHP
        REP #$30
        LDA.W $12D2
        AND.W #$0003
        BNE ProcessAnimationFrame
        INC.W $12DA
; [Animation] Processes animation frame data and updates registers.
ProcessAnimationFrame:
        LDA.W $12DA
        AND.W #$0003
        ASL A
        TAX
        LDA.W $E555,X
        TAY
        LDX.W $12CE
        LDA.W $E55D,X
        STA.B $00
        LDA.W #$00C0
        STA.B $02
        LDA.B [$00],Y
        STA.W $041E
        PLP
        RTS
        db $3E,$00,$3C,$00,$3A,$00,$3C,$00,$1E,$00,$1C,$00,$1A,$00,$1C,$00
        db $40,$08
        db $60,$08,$40,$08,$40,$08,$40,$08,$40,$08,$40,$08,$40,$08
        db $00,$00,$00,$00,$00,$01,$00,$00,$00,$02,$00,$00,$00,$03,$00,$00
        db $00,$00,$00,$01,$00,$01,$00,$01,$00,$02,$00,$01,$00,$03,$00,$01
; [StateMachine] Dispatches to handler based on $0C value. Entry: 8-bit A, 16-bit X/Y.
DispatchBy0C:
        SEP #$20
        REP #$10
        LDA.B #$00
        XBA
        LDA.B $0C
        TAX
        JMP.W ($E59A,X)
        db $FA,$E5
        db $9E,$E5
        REP #$20
        SEP #$30
        JSR.W UpdateGameCounter
        JSR.W UpdateTimerA0A1
        LDA.B $93
