        LDA.B $91
        ASL A
        ASL A
        TAX
        LDA.W $E5ED,X
        CMP.B #$FF
        BEQ Clear0CAndJump
        STA.B $10
        LDA.W $E5EE,X
        PHA
        AND.B #$7F
        STA.B $93
        PLA
        AND.B #$80
        STA.B $4A
        LDA.W $E5EF,X
        STA.B $42
        LDA.W $E5F0,X
        STA.B $AE
        STZ.B $41
        LDA.B #$9A
        STA.B $40
        LDA.B #$0C
        STA.B $48
        LDA.B #$18
        STA.B $AD
        INC.B $91
; [Helper] Decrements $93 counter and jumps to $8471.
Decrement93AndJump:
        DEC.B $93
        JMP.W CheckEntityTypeAndDispatch
; [Helper] Clears $0C and jumps to $8471 with 16-bit mode.
Clear0CAndJump:
        STZ.B $0C
        REP #$20
        JMP.W CheckEntityTypeAndDispatch
        db $54,$07,$00,$00,$55,$90,$02,$03,$55,$01,$00,$00,$FF
        SEP #$20
        REP #$10
        LDA.B #$00
        XBA
        LDA.B $0B
        TAX
        JMP.W ($E607,X)
        db $B8,$E8,$6B,$E8,$6F,$E6
        db $65,$E6
        db $42,$E6,$13,$E6
        DEC.B $A0
        BEQ CopyMemoryAndCheck
        LDA.B $27
        BNE UnknownFunction628
        LDA.B $A0
        LSR A
